  static getThisMonth(): AbsoluteTimeRange {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    return {
      from: startOfMonth.getTime(),
      to: Date.now(),
    };
  }

